// The axes of a chart beyond the plain pair: a second scale at the right,
// axes on the side they say they stand on, labels at the far end, turned
// category labels and two levels of them, a logarithmic value axis and a
// date axis. Every chart part is generated by code; text is measured by a
// stand-in (half the font size per character).
//
// Excel is not at hand: what follows its known behaviour without having been
// compared with it is marked UNSURE.

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { open, type Chart, type DrawingChart, type Workbook } from '../src/index';
import { chartLogScale, chartValues, layoutChart, type ChartItem, type ChartLayout, type ChartScale } from '../src/layout/chart';
import { catAx, chartFrameOf, chartWorkbook, chartXml, fakeMeasure, group, numLit, numRef, readChart, ser, sheetData, strLit, valAx, xySer } from './chart-fixtures';
import { twoCell } from './sheet-drawing-fixtures';

type Of<K extends ChartItem['kind']> = Extract<ChartItem, { kind: K }>;

function model(xml: string): Chart {
  const chart = readChart(xml);
  assert.ok(chart, 'the chart is read');
  return chart as Chart;
}

const lay = (xml: string, width = 480, height = 320): ChartLayout => {
  const chart = model(xml);
  return layoutChart(chart, chartValues(chart), width, height, fakeMeasure);
};
const items = <K extends ChartItem['kind']>(layout: ChartLayout, kind: K, role?: string): Of<K>[] => layout.items.filter((item) => item.kind === kind && (role === undefined || item.role === role)) as Of<K>[];
const texts = (layout: ChartLayout, role: string): string[] => items(layout, 'text', role).map((item) => item.text);
const near = (actual: number, expected: number, message: string, tolerance = 1e-6) => assert.ok(Math.abs(actual - expected) <= tolerance, `${message}: ${actual} is not ${expected}`);
const right = (layout: ChartLayout) => layout.plot.x + layout.plot.width;
const bottom = (layout: ChartLayout) => layout.plot.y + layout.plot.height;

const CATS = strLit(['Ocak', 'Şubat', 'Mart']);
const axis = (name: string, id: number, cross: number, position: string, inner = '', scaling = '<c:orientation val="minMax"/>') =>
  `<c:${name}><c:axId val="${id}"/><c:scaling>${scaling}</c:scaling><c:delete val="0"/><c:axPos val="${position}"/>${inner}<c:crossAx val="${cross}"/></c:${name}>`;
const bars = (values: number[], ids = '<c:axId val="1"/><c:axId val="2"/>', dir = 'col') =>
  `<c:barChart><c:barDir val="${dir}"/><c:grouping val="clustered"/>${ser(0, { cat: CATS, val: numLit(values) })}${ids}</c:barChart>`;
const line = (values: (number | null)[], ids = '<c:axId val="3"/><c:axId val="4"/>', index = 1, cats = CATS) =>
  `<c:lineChart><c:grouping val="standard"/>${ser(index, { cat: cats, val: numLit(values) })}<c:marker val="1"/>${ids}</c:lineChart>`;

// ------------------------------------------------------------ a second scale

const SECOND = (valInner = '<c:crosses val="max"/>', catInner = '<c:delete val="1"/>') =>
  `<c:catAx><c:axId val="3"/><c:scaling><c:orientation val="minMax"/></c:scaling>${catInner}<c:axPos val="b"/><c:crossAx val="4"/></c:catAx>` +
  axis('valAx', 4, 3, 'r', '<c:numFmt formatCode="0.0" sourceLinked="0"/>' + valInner, '<c:orientation val="minMax"/><c:max val="1000"/><c:min val="0"/>');
const twoScales = (second = SECOND(), firstVal = '<c:majorGridlines/>') =>
  chartXml({ plot: bars([10, 20, 40]) + line([100, 500, 900]) + axis('catAx', 1, 2, 'b') + axis('valAx', 2, 1, 'l', firstVal, '<c:orientation val="minMax"/><c:max val="40"/><c:min val="0"/>') + second });

test('a second pair of axes: its series are drawn against its own scale, and its value axis stands at the right', () => {
  const layout = lay(twoScales());
  assert.deepEqual([layout.scale?.min, layout.scale?.max], [0, 40], 'the first scale');
  assert.deepEqual([layout.scale2?.min, layout.scale2?.max], [0, 1000], 'the second scale');
  const columns = items(layout, 'rect', 'bar');
  near(columns[2].y, layout.plot.y, 'the column of 40 reaches the top of the first scale');
  const points = items(layout, 'path', 'line')[0].points;
  near(points[1], bottom(layout) - 0.1 * layout.plot.height, '100 of 1000 on the second scale');
  near(points[5], bottom(layout) - 0.9 * layout.plot.height, '900 of 1000');
  near(points[0], columns[0].x + columns[0].width / 2, 'the categories are shared');
  const ticks = items(layout, 'text', 'tick');
  const atLeft = ticks.filter((item) => item.x < layout.plot.x);
  const atRight = ticks.filter((item) => item.x > right(layout));
  assert.ok(atLeft.some((item) => item.text === '40') && atLeft.every((item) => item.align === 'right'), 'the labels of the first scale at the left');
  assert.ok(atRight.some((item) => item.text === '1000.0') && atRight.every((item) => item.align === 'left'), 'the labels of the second scale at the right, in its own format');
  assert.equal(atLeft.length + atRight.length, ticks.length, 'no label inside the plot area');
  const axes = items(layout, 'path', 'axis');
  assert.ok(axes.some((item) => Math.abs(item.points[0] - right(layout)) <= 0.5 && Math.abs(item.points[2] - right(layout)) <= 0.5), 'a line for the axis at the right');
  assert.equal(texts(layout, 'category').join(), 'Ocak,Şubat,Mart', 'the deleted second category axis shows nothing');
  for (const item of ticks) assert.ok(item.x >= 0 && item.x <= layout.width, `the label ${item.text} lies in the frame`);
});

test('a second value axis has a title of its own beside it; one that is deleted takes no room', () => {
  const titled = lay(twoScales(SECOND('<c:crosses val="max"/><c:title><c:tx><c:rich><a:bodyPr/><a:p><a:r><a:t>Adet</a:t></a:r></a:p></c:rich></c:tx></c:title>')));
  const title = items(titled, 'text', 'axisTitle').filter((item) => item.text === 'Adet')[0];
  assert.ok(title && title.x > right(titled) && title.rotated === true, 'the title of the second axis stands at the right, turned');
  const plain = lay(twoScales());
  assert.ok(right(titled) < right(plain), 'and takes room from the plot area');
  const hidden = lay(twoScales(SECOND('<c:crosses val="max"/>').replace('<c:axId val="4"/><c:scaling>', '<c:axId val="4"/><c:scaling>').replace('<c:delete val="0"/><c:axPos val="r"/>', '<c:delete val="1"/><c:axPos val="r"/>')));
  assert.equal(items(hidden, 'text', 'tick').filter((item) => item.x > right(hidden)).length, 0, 'a deleted second axis has no labels');
  assert.deepEqual([hidden.scale2?.min, hidden.scale2?.max], [0, 1000], 'but its scale still places its series');
  assert.ok(right(hidden) > right(plain), 'and the plot area has the room');
});

test('a second pair that does not say where it stands goes to the other side (UNSURE)', () => {
  // Neither crosses="max" nor a side: Excel would draw both axes at the left, one over the other.
  const layout = lay(twoScales(SECOND('').replace('<c:axPos val="r"/>', '<c:axPos val="l"/>')));
  assert.ok(items(layout, 'text', 'tick').some((item) => item.x > right(layout) && item.text === '1000.0'), 'the second scale at the right');
});

test('a second category axis that is not deleted is drawn on the other side of the plot area', () => {
  const layout = lay(twoScales(SECOND('<c:crosses val="max"/>', '<c:delete val="0"/>')));
  const categories = items(layout, 'text', 'category');
  assert.equal(categories.filter((item) => item.y > bottom(layout)).length, 3, 'the first at the bottom');
  assert.equal(categories.filter((item) => item.y < layout.plot.y).length, 3, 'the second at the top');
  assert.ok(layout.plot.y > lay(twoScales()).plot.y, 'which takes room');
});

test('all series on the second pair only: one scale, and it is the first of the layout', () => {
  const xml = chartXml({ plot: line([100, 500, 900], '<c:axId val="3"/><c:axId val="4"/>', 0) + axis('catAx', 1, 2, 'b') + axis('valAx', 2, 1, 'l') + SECOND() });
  const layout = lay(xml);
  assert.deepEqual([layout.scale?.max, layout.scale2], [1000, undefined]);
  assert.ok(items(layout, 'text', 'tick').every((item) => item.x > right(layout)), 'its labels stand where its axis says: at the right');
});

// --------------------------------------------------------------------- sides

const upright = (cat: string, val: string, values = [10, 20, 30]) => chartXml({ plot: bars(values) + cat + val });

test('a value axis stands on the side it says, or where it crosses the categories', () => {
  const said = lay(upright(axis('catAx', 1, 2, 'b'), axis('valAx', 2, 1, 'r')));
  const ticks = items(said, 'text', 'tick');
  assert.ok(ticks.length > 0 && ticks.every((item) => item.x > right(said) && item.align === 'left'), 'axPos r: the labels at the right');
  assert.ok(said.plot.x < 20, 'and no room is kept at the left');
  const crossed = lay(upright(axis('catAx', 1, 2, 'b'), axis('valAx', 2, 1, 'l', '<c:crosses val="max"/>')));
  assert.ok(items(crossed, 'text', 'tick').every((item) => item.x > right(crossed)), 'crosses max: at the end of the categories, whatever the side says');
});

test('categories in reverse order take the value axis to the other side; values in reverse order take the category axis to the top', () => {
  const reversedCats = lay(upright(axis('catAx', 1, 2, 'b', '', '<c:orientation val="maxMin"/>'), axis('valAx', 2, 1, 'l')));
  assert.ok(items(reversedCats, 'text', 'tick').every((item) => item.x > right(reversedCats)), 'the value axis at the right');
  const columns = items(reversedCats, 'rect', 'bar');
  assert.ok(columns[0].x > columns[2].x, 'the first category at the right');
  const back = lay(upright(axis('catAx', 1, 2, 'b', '', '<c:orientation val="maxMin"/>'), axis('valAx', 2, 1, 'l', '<c:crosses val="max"/>')));
  assert.ok(items(back, 'text', 'tick').every((item) => item.x < back.plot.x), 'crossing at the last category, which is now at the left');

  const reversedVals = lay(upright(axis('catAx', 1, 2, 'b'), axis('valAx', 2, 1, 'l', '', '<c:orientation val="maxMin"/>')));
  const categories = items(reversedVals, 'text', 'category');
  assert.ok(categories.length === 3 && categories.every((item) => item.y < reversedVals.plot.y), 'the category labels at the top, beside zero');
  near(items(reversedVals, 'rect', 'bar')[0].y, reversedVals.plot.y, 'the columns hang from the top');
  const top = lay(upright(axis('catAx', 1, 2, 't'), axis('valAx', 2, 1, 'l')));
  assert.ok(items(top, 'text', 'category').every((item) => item.y < top.plot.y), 'axPos t: the category labels at the top');
  const max = lay(upright(axis('catAx', 1, 2, 'b', '<c:crosses val="max"/>'), axis('valAx', 2, 1, 'l')));
  assert.ok(items(max, 'text', 'category').every((item) => item.y < max.plot.y), 'crossing the value axis at its maximum: labels beside the axis, at the top');
});

test('labels at the high or the low end of the other axis, whatever side the axis stands on', () => {
  const high = lay(upright(axis('catAx', 1, 2, 'b'), axis('valAx', 2, 1, 'l', '<c:tickLblPos val="high"/>')));
  assert.ok(items(high, 'text', 'tick').every((item) => item.x > right(high)), 'value labels "high": at the right');
  assert.ok(items(high, 'path', 'axis').some((item) => Math.abs(item.points[0] - high.plot.x) <= 0.5 && Math.abs(item.points[2] - high.plot.x) <= 0.5), 'the line of the axis stays at the left');
  const low = lay(upright(axis('catAx', 1, 2, 'b', '<c:crosses val="max"/><c:tickLblPos val="low"/>'), axis('valAx', 2, 1, 'l')));
  assert.ok(items(low, 'text', 'category').every((item) => item.y > bottom(low)), 'category labels "low": at the bottom, though the axis is at the top');
  const catHigh = lay(upright(axis('catAx', 1, 2, 'b', '<c:tickLblPos val="high"/>'), axis('valAx', 2, 1, 'l')));
  assert.ok(items(catHigh, 'text', 'category').every((item) => item.y < catHigh.plot.y), 'category labels "high": at the top');
});

test('bars that lie: categories at the left and values below, or where the axes say', () => {
  const lying = (cat: string, val: string) => chartXml({ plot: bars([10, 20, 30], undefined, 'bar') + cat + val });
  const plain = lay(lying(axis('catAx', 1, 2, 'l'), axis('valAx', 2, 1, 'b')));
  assert.ok(items(plain, 'text', 'category').every((item) => item.x < plain.plot.x), 'categories at the left');
  assert.ok(items(plain, 'text', 'tick').every((item) => item.y > bottom(plain)), 'values below');
  const top = lay(lying(axis('catAx', 1, 2, 'l'), axis('valAx', 2, 1, 't')));
  assert.ok(items(top, 'text', 'tick').every((item) => item.y < top.plot.y), 'axPos t: values above');
  const reversed = lay(lying(axis('catAx', 1, 2, 'l', '', '<c:orientation val="maxMin"/>'), axis('valAx', 2, 1, 'b')));
  assert.ok(items(reversed, 'text', 'tick').every((item) => item.y < reversed.plot.y), 'categories from the top down: the value axis at the top');
  const bars3 = items(reversed, 'rect', 'bar');
  assert.ok(bars3[0].y < bars3[2].y, 'the first category at the top');
  const rightSide = lay(lying(axis('catAx', 1, 2, 'r'), axis('valAx', 2, 1, 'b')));
  assert.ok(items(rightSide, 'text', 'category').every((item) => item.x > right(rightSide) && item.align === 'left'), 'axPos r: categories at the right');
  const flipped = lay(lying(axis('catAx', 1, 2, 'l'), axis('valAx', 2, 1, 'b', '', '<c:orientation val="maxMin"/>')));
  assert.ok(items(flipped, 'text', 'category').every((item) => item.x > right(flipped)), 'values from right to left: zero and the categories at the right');
});

// ------------------------------------------------------------- turned labels

const wide = (labels: string[], catInner = '', width = 480, height = 320) =>
  lay(chartXml({ plot: group('barChart', '<c:barDir val="col"/><c:grouping val="clustered"/>', ser(0, { cat: strLit(labels), val: numLit(labels.map((_label, i) => i + 1)) })) + catAx(catInner) + valAx() }), width, height);
const LONG = (count: number) => Array.from({ length: count }, (_value, i) => `Uzun kategori adı ${i + 1}`);

test('category labels that fit lie flat; ones that do not are turned by 45 degrees, then by 90', () => {
  const flat = wide(['a', 'b', 'c']);
  assert.ok(items(flat, 'text', 'category').every((item) => item.angle === undefined && item.align === 'center'), 'short labels lie flat');
  const slanted = wide(LONG(5));
  const turned = items(slanted, 'text', 'category');
  assert.equal(turned.length, 5, 'every label is shown');
  assert.ok(turned.every((item) => item.angle === -45 && item.align === 'right'), 'at 45 degrees, ending at their ticks');
  assert.deepEqual(turned.map((item) => item.text), LONG(5), 'in full');
  assert.ok(bottom(slanted) < bottom(flat) - 20, 'the plot area makes room below');
  const steep = wide(LONG(24));
  const upright90 = items(steep, 'text', 'category');
  assert.equal(upright90.length, 24, 'two dozen labels are all shown');
  assert.ok(upright90.every((item) => item.angle === -90), 'standing');
  for (const layout of [slanted, steep]) {
    for (const item of items(layout, 'text', 'category')) {
      const length = fakeMeasure(item.text, item.font);
      const turn = ((item.angle || 0) * Math.PI) / 180;
      // The text ends at (x, y) and runs back from there.
      const startX = item.x - length * Math.cos(turn);
      const startY = item.y - length * Math.sin(turn);
      assert.ok(startX >= -0.5 && startY <= layout.height + 0.5 && item.y >= bottom(layout), `"${item.text}" stays in the frame (${startX}, ${startY})`);
    }
  }
});

test('labels that do not fit even standing are thinned out and lie flat, as before', () => {
  const crowded = wide(LONG(400));
  const shown = items(crowded, 'text', 'category');
  assert.ok(shown.length > 0 && shown.length < 60, `${shown.length} of 400 labels are shown`);
  assert.ok(shown.every((item) => item.angle === undefined), 'flat');
});

test('a turn the file states is taken as it is: upwards, downwards, or none', () => {
  const rot = (value: string) => `<c:txPr><a:bodyPr rot="${value}"/><a:p><a:pPr><a:defRPr/></a:pPr></a:p></c:txPr>`;
  const up = items(wide(['a', 'b', 'c'], rot('-5400000')), 'text', 'category');
  assert.ok(up.every((item) => item.angle === -90 && item.align === 'right'), 'rot -90: read from the bottom up, ending at the axis');
  const down = items(wide(['a', 'b', 'c'], rot('2700000')), 'text', 'category');
  assert.ok(down.every((item) => item.angle === 45 && item.align === 'left'), 'rot 45: read downwards, starting at the axis');
  const none = items(wide(LONG(5), rot('0')), 'text', 'category');
  assert.ok(none.length > 0 && none.every((item) => item.angle === undefined), 'rot 0: flat, thinned and cut where they do not fit');
});

test('a tall band of turned labels never takes more than a part of the frame; long ones are cut', () => {
  const layout = wide(Array.from({ length: 12 }, (_value, i) => `${'çok '.repeat(40)}uzun ${i}`), '', 480, 320);
  assert.ok(layout.plot.height > 320 * 0.4, `the plot area keeps most of the height (${layout.plot.height})`);
  assert.ok(items(layout, 'text', 'category').every((item) => item.text.endsWith('…')), 'the labels are cut');
});

// ------------------------------------------------------ levels of categories

const LEVELS =
  '<c:multiLvlStrRef><c:f>Sayfa1!$A$1:$B$4</c:f><c:multiLvlStrCache><c:ptCount val="4"/>' +
  '<c:lvl><c:pt idx="0"><c:v>Oca</c:v></c:pt><c:pt idx="1"><c:v>Şub</c:v></c:pt><c:pt idx="2"><c:v>Oca</c:v></c:pt><c:pt idx="3"><c:v>Şub</c:v></c:pt></c:lvl>' +
  '<c:lvl><c:pt idx="0"><c:v>2024</c:v></c:pt><c:pt idx="2"><c:v>2025</c:v></c:pt></c:lvl>' +
  '</c:multiLvlStrCache></c:multiLvlStrRef>';
const levelChart = chartXml({ plot: group('barChart', '<c:barDir val="col"/><c:grouping val="clustered"/>', ser(0, { cat: LEVELS, val: numRef('Sayfa1!$C$1:$C$4', [1, 2, 3, 4]) })) + catAx() + valAx() });

test('two levels of categories are two rows: the outer one below, each label across the categories it holds', () => {
  const layout = lay(levelChart);
  const rows = items(layout, 'text', 'category');
  const inner = rows.filter((item) => item.text === 'Oca' || item.text === 'Şub');
  const outer = rows.filter((item) => item.text === '2024' || item.text === '2025');
  assert.deepEqual([inner.length, outer.length], [4, 2]);
  assert.ok(outer.every((item) => item.y > inner[0].y + 5), 'the outer row lies below the inner one');
  const columns = items(layout, 'rect', 'bar');
  const centre = (i: number) => columns[i].x + columns[i].width / 2;
  near(outer[0].x, (centre(0) + centre(1)) / 2, '2024 is centred over its two categories');
  near(outer[1].x, (centre(2) + centre(3)) / 2, '2025 over the other two');
  const one = lay(chartXml({ plot: group('barChart', '<c:barDir val="col"/><c:grouping val="clustered"/>', ser(0, { cat: strLit(['Oca', 'Şub', 'Oca', 'Şub']), val: numLit([1, 2, 3, 4]) })) + catAx() + valAx() }));
  assert.ok(bottom(layout) < bottom(one) - 8, 'the second row takes room from the plot area');
});

test('two levels of categories from the cells: the last column next to the axis, the one before it outside', async () => {
  const bytes = await chartWorkbook({ sheet: sheetData([['Yıl A', 'Ç1', 5], [null, 'Ç2', 6], ['Yıl B', 'Ç1', 7], [null, 'Ç2', 8]]), drawing: twoCell([0, 5], [6, 20], chartFrameOf('rIdC1')), charts: [levelChart] });
  const workbook = (await (await open(bytes)).workbook()) as Workbook;
  const chart = (workbook.sheets[0].drawings![0].object as DrawingChart).chart as Chart;
  const values = chartValues(chart, { workbook });
  assert.deepEqual([values.label(0), values.label(1), values.label(3)], ['Ç1', 'Ç2', 'Ç2']);
  assert.equal(typeof values.outerLabel, 'function', 'the values know of a second level');
  assert.deepEqual([0, 1, 2, 3].map((i) => (values.outerLabel as (index: number) => string)(i)), ['Yıl A', '', 'Yıl B', '']);
  const layout = layoutChart(chart, values, 480, 320, fakeMeasure);
  assert.deepEqual(texts(layout, 'category').sort(), ['Yıl A', 'Yıl B', 'Ç1', 'Ç1', 'Ç2', 'Ç2'].sort());
});

// --------------------------------------------------------- a logarithmic axis

function assertScale(scale: ChartScale, message: string): void {
  assert.ok(Number.isFinite(scale.min) && Number.isFinite(scale.max) && scale.max > scale.min, `${message}: ${scale.min}..${scale.max}`);
  assert.ok(scale.ticks.length >= 2 && scale.ticks.length <= 201, `${message}: ${scale.ticks.length} ticks`);
  for (let i = 0; i < scale.ticks.length; i++) {
    assert.ok(Number.isFinite(scale.ticks[i]) && scale.ticks[i] > 0, `${message}: tick ${i} is ${scale.ticks[i]}`);
    if (i > 0) assert.ok(scale.ticks[i] > scale.ticks[i - 1], `${message}: ticks go upwards`);
  }
}

test('a logarithmic scale: from the power below the smallest value to the power above the largest, a tick at every power', () => {
  const scale = chartLogScale(3, 4500, 10);
  assert.deepEqual([scale.min, scale.max, scale.log], [1, 10000, 10]);
  assert.deepEqual(scale.ticks, [1, 10, 100, 1000, 10000]);
  assert.deepEqual(chartLogScale(1, 100, 10).ticks, [1, 10, 100], 'values that are powers are the ends');
  assert.deepEqual(chartLogScale(0.02, 0.5, 10).ticks, [0.01, 0.1, 1], 'below one');
  assert.deepEqual(chartLogScale(3, 40, 2).ticks, [2, 4, 8, 16, 32, 64], 'base two');
  assert.deepEqual(chartLogScale(5, 5, 10).ticks, [1, 10], 'one value');
  assert.deepEqual(chartLogScale(-5, 0, 10).ticks, [1, 10], 'nothing above zero: one power');
  assert.deepEqual(chartLogScale(1, 1e12, 10, { maxSteps: 4 }).ticks, [1, 1000, 1e6, 1e9, 1e12], 'more powers than there is room for: every n-th');
  assert.deepEqual([chartLogScale(3, 4500, 10, { min: 100, max: 1e6 }).min, chartLogScale(3, 4500, 10, { min: 100, max: 1e6 }).max], [100, 1e6], 'what the axis states');
  assert.deepEqual(chartLogScale(3, 4500, 10, { min: -5, max: 0 }).ticks, [1, 10, 100, 1000, 10000], 'ends that are not above zero are not taken');
  for (const [low, high, base] of [[5e-324, 1.7e308, 10], [1e-320, 1e-310, 2], [1e300, 1.7e308, 1000], [NaN, Infinity, 10], [7, 3, 2.5], [1, 1, 1000], [0, 0, 7]] as [number, number, number][]) {
    assertScale(chartLogScale(low, high, base), `${low}..${high} to base ${base}`);
  }
  for (const base of [NaN, 0, 1, -3, Infinity, 1e9]) assertScale(chartLogScale(1, 1000, base), `base ${base} is taken as ten`);
});

test('a logarithmic value axis: equal steps for equal factors; values that are not above zero are left out', () => {
  const logAxis = (inner = '') => valAx('<c:majorGridlines/>' + inner, '<c:logBase val="10"/><c:orientation val="minMax"/>');
  const layout = lay(chartXml({ plot: group('lineChart', '<c:grouping val="standard"/>', ser(0, { cat: strLit(['a', 'b', 'c', 'd', 'e']), val: numLit([1, 10, 100, 0, -5]) }), '<c:marker val="1"/>') + catAx() + logAxis() }));
  assert.deepEqual([layout.scale?.min, layout.scale?.max, layout.scale?.log], [1, 100, 10]);
  const points = items(layout, 'path', 'line')[0].points;
  assert.equal(points.length, 6, 'the points of zero and below are not drawn');
  near(points[1], bottom(layout), '1 at the bottom');
  near(points[3], layout.plot.y + layout.plot.height / 2, '10 halfway');
  near(points[5], layout.plot.y, '100 at the top');
  assert.deepEqual(texts(layout, 'tick'), ['1', '10', '100']);
  const grid = items(layout, 'path', 'grid').map((item) => item.points[1]);
  near(Math.abs(grid[1] - grid[0]), layout.plot.height / 2, 'grid lines at the powers (on whole pixels)', 1);
  // Columns stand on the bottom of the axis: there is no zero to stand on.
  const columns = lay(chartXml({ plot: group('barChart', '<c:barDir val="col"/><c:grouping val="clustered"/>', ser(0, { cat: CATS, val: numLit([10, 1000, -3]) })) + catAx() + logAxis() }));
  const rects = items(columns, 'rect', 'bar');
  assert.equal(rects.length, 2, 'no column for a value below zero');
  near(rects[0].y + rects[0].height, bottom(columns), 'standing on the bottom');
  near(rects[1].height, columns.plot.height, '1000 of 10..1000');
  near(rects[0].height, 0, '10 is the bottom itself');
  // A scatter chart with both axes logarithmic.
  const xy = lay(
    chartXml({
      plot:
        group('scatterChart', '<c:scatterStyle val="lineMarker"/>', xySer(0, { cat: numLit([1, 10, 100]), val: numLit([1000, 100, 10]) })) +
        axis('valAx', 111, 222, 'b', '', '<c:logBase val="10"/>') +
        axis('valAx', 222, 111, 'l', '', '<c:logBase val="10"/>'),
    }),
  );
  const marks = items(xy, 'markers', 'marker')[0].points;
  near(marks[2], xy.plot.x + xy.plot.width / 2, 'x = 10 halfway along');
  near(marks[3], xy.plot.y + xy.plot.height / 2, 'y = 100 halfway up');
  assert.deepEqual([xy.xScale?.log, xy.scale?.log], [10, 10]);
});

// ----------------------------------------------------------------- date axis

/** 2024-01-01 is serial 45292. */
const D = 45292;
const dateAxis = (inner = '', format = 'd.m.yyyy') => `<c:dateAx><c:axId val="111"/><c:scaling><c:orientation val="minMax"/></c:scaling><c:delete val="0"/><c:axPos val="b"/><c:numFmt formatCode="${format}" sourceLinked="0"/>${inner}<c:crossAx val="222"/></c:dateAx>`;
const dated = (serials: number[], values: number[], inner = '', type = 'lineChart', format?: string) =>
  chartXml({ plot: group(type, type === 'barChart' ? '<c:barDir val="col"/><c:grouping val="clustered"/>' : '<c:grouping val="standard"/>', ser(0, { cat: numLit(serials), val: numLit(values) }), type === 'lineChart' ? '<c:marker val="1"/>' : '') + dateAxis(inner, format) + valAx() });

test('a date axis places its points where their dates lie, not side by side', () => {
  // The first, the second and the tenth of January: ten days across.
  const layout = lay(dated([D, D + 1, D + 9], [1, 2, 3], '<c:baseTimeUnit val="days"/>'));
  const points = items(layout, 'path', 'line')[0].points;
  const day = layout.plot.width / 10;
  near(points[0], layout.plot.x + 0.5 * day, 'the first day in the middle of its day');
  near(points[2], layout.plot.x + 1.5 * day, 'the second next to it');
  near(points[4], layout.plot.x + 9.5 * day, 'the tenth at the end');
  const labels = items(layout, 'text', 'category');
  assert.equal(labels[0].text, '1.1.2024', 'the labels are dates in the format of the axis');
  assert.ok(labels.length >= 2 && labels.length <= 10, `${labels.length} labels`);
  for (let i = 1; i < labels.length; i++) assert.ok(labels[i].x - labels[i - 1].x >= fakeMeasure(labels[i].text, labels[i].font), 'no label runs into the next');
});

test('a date axis sorts its points by date, and columns are as wide as their unit allows', () => {
  const layout = lay(dated([D + 9, D, D + 4], [3, 1, 2], '<c:baseTimeUnit val="days"/>'));
  const points = items(layout, 'path', 'line')[0].points;
  assert.ok(points[0] < points[2] && points[2] < points[4], 'the line runs from left to right');
  near(points[1], bottom(layout) - (1 / (layout.scale as ChartScale).max) * layout.plot.height, 'starting with the value of the earliest date');
  const columns = items(lay(dated([D, D + 1, D + 9], [1, 2, 3], '<c:baseTimeUnit val="days"/>', 'barChart')), 'rect', 'bar');
  assert.equal(columns.length, 3);
  assert.ok(columns[0].width > 0 && columns[0].x + columns[0].width <= columns[1].x + 1e-9, 'columns of neighbouring days do not overlap');
  assert.ok(columns[2].x - columns[1].x > columns[1].x - columns[0].x, 'the gap of eight days shows');
});

test('a date axis counts in months or years when it says so, and its ticks follow the unit of the file', () => {
  // 15 Jan, 20 Feb, 5 Jun 2024: months 0, 1 and 5 of six.
  const months = lay(dated([D + 14, D + 50, D + 156], [1, 2, 3], '<c:baseTimeUnit val="months"/><c:majorUnit val="1"/><c:majorTimeUnit val="months"/>', 'lineChart', 'mmm'));
  const points = items(months, 'path', 'line')[0].points;
  const month = months.plot.width / 6;
  near(points[0], months.plot.x + 0.5 * month, 'January');
  near(points[2], months.plot.x + 1.5 * month, 'February');
  near(points[4], months.plot.x + 5.5 * month, 'June');
  assert.deepEqual(texts(months, 'category'), ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'], 'a label for every month, with or without a point');
  const quarters = lay(dated([D + 14, D + 50, D + 156], [1, 2, 3], '<c:baseTimeUnit val="months"/><c:majorUnit val="3"/><c:majorTimeUnit val="months"/>', 'lineChart', 'mmm'));
  assert.deepEqual(texts(quarters, 'category'), ['Jan', 'Apr'], 'every third month');
  const years = lay(dated([D, D + 366, D + 366 + 365 * 3], [1, 2, 3], '<c:baseTimeUnit val="years"/>', 'lineChart', 'yyyy'));
  assert.deepEqual(texts(years, 'category'), ['2024', '2025', '2026', '2027', '2028']);
  const guessed = lay(dated([D, D + 31, D + 60], [1, 2, 3], '', 'lineChart', 'mmm'));
  assert.deepEqual(texts(guessed, 'category'), ['Jan', 'Feb', 'Mar'], 'UNSURE: dates a month apart count in months when the axis does not say');
});

test('a date axis with categories that are no dates is a category axis; many dates are thinned to what fits', () => {
  const texty = lay(chartXml({ plot: group('lineChart', '<c:grouping val="standard"/>', ser(0, { cat: strLit(['a', 'b', 'c']), val: numLit([1, 2, 3]) })) + dateAxis() + valAx() }));
  assert.deepEqual(texts(texty, 'category'), ['a', 'b', 'c']);
  const partly = lay(dated([D, -5, D + 2], [1, 2, 3]));
  assert.equal(items(partly, 'path', 'line')[0].points.length, 6, 'a serial number that is no date: side by side');
  near(items(partly, 'path', 'line')[0].points[2], partly.plot.x + partly.plot.width / 2, 'the second in the middle');
  // Ten years of days: sampled like any long series, placed by date, with labels that fit.
  const serials = Array.from({ length: 3650 }, (_value, i) => D + i);
  const long = lay(dated(serials, serials.map((_value, i) => i % 50), '<c:baseTimeUnit val="days"/>'));
  const labels = items(long, 'text', 'category');
  assert.ok(labels.length >= 2 && labels.length <= 12, `${labels.length} labels for ten years`);
  for (let i = 1; i < labels.length; i++) assert.ok(labels[i].x - labels[i - 1].x >= fakeMeasure(labels[i].text, labels[i].font), 'no label runs into the next');
  // Bars that lie keep their categories side by side: the dates are labels there, not places.
  const lying = lay(chartXml({ plot: group('barChart', '<c:barDir val="bar"/><c:grouping val="clustered"/>', ser(0, { cat: numLit([D, D + 1, D + 9]), val: numLit([1, 2, 3]) })) + dateAxis('<c:baseTimeUnit val="days"/>') + valAx() }));
  const rows = items(lying, 'rect', 'bar');
  near(rows[0].y - rows[1].y, rows[1].y - rows[2].y, 'bars that lie are evenly apart on a date axis');
  assert.equal(items(lying, 'text', 'category').length, 3, 'with a label each');
  const far = lay(dated([1, 2958465], [1, 2], '<c:baseTimeUnit val="days"/>'));
  assert.ok(items(far, 'text', 'category').length <= 12 && items(far, 'path', 'line')[0].points.every((value) => Number.isFinite(value)), 'from 1900 to 9999 in days: still an axis');
});

test('dates count from 1904 where the workbook says so', () => {
  const chart = model(dated([0, 1, 2], [1, 2, 3], '<c:baseTimeUnit val="days"/>'));
  const from1904 = layoutChart(chart, chartValues(chart), 480, 320, fakeMeasure, { date1904: true });
  assert.equal(items(from1904, 'text', 'category')[0].text, '1.1.1904');
});
